package com.arun.mymessages;
import android.content.*;import android.app.*;import android.os.*;import android.provider.Telephony;import android.telephony.SmsMessage;import android.graphics.Color;
public class SmsReceiver extends BroadcastReceiver{
 public void onReceive(Context c,Intent i){if(!Telephony.Sms.Intents.SMS_DELIVER_ACTION.equals(i.getAction()))return;SmsMessage[] m=Telephony.Sms.Intents.getMessagesFromIntent(i);if(m==null)return;String from=m.length>0?m[0].getDisplayOriginatingAddress():"SMS";String body="";for(SmsMessage x:m)body+=x.getMessageBody();boolean otp=body.matches("(?is).*\\b(otp|one[- ]?time|verification|verify|code)\\b.*\\b\\d{4,8}\\b.*");if(Build.VERSION.SDK_INT>=26)((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("sms","SMS",NotificationManager.IMPORTANCE_HIGH));Notification.Builder n=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"sms"):new Notification.Builder(c);n.setSmallIcon(android.R.drawable.sym_action_email).setContentTitle(otp?"OTP • "+from:from).setContentText(((android.content.SharedPreferences)c.getSharedPreferences("settings",0)).getBoolean("hidePreview",false)?"New message":body).setAutoCancel(true);
 Intent open=new Intent(c,ConversationActivity.class);open.putExtra("number",from);open.putExtra("name",from);n.setContentIntent(PendingIntent.getActivity(c,(int)System.currentTimeMillis(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
 if(Build.VERSION.SDK_INT>=24){android.app.RemoteInput ri=new android.app.RemoteInput.Builder("reply").setLabel("Reply").build();Intent rep=new Intent(c,SmsReplyReceiver.class).putExtra("number",from);PendingIntent rp=PendingIntent.getBroadcast(c,(int)(System.currentTimeMillis()%100000),rep,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);n.addAction(new Notification.Action.Builder(android.graphics.drawable.Icon.createWithResource(c,android.R.drawable.ic_menu_send),"Reply",rp).addRemoteInput(ri).build());}
 ((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify((int)(System.currentTimeMillis()%100000),n.build());}
}